// 已提交命令的键值应用：把日志命令解释为 set/delete/incr 键值操作，在本次调用内
// 从空键值表开始，随提交位置推进按日志索引顺序应用。本文件只做纯逻辑处理。
package mevwatch

import (
	"strconv"
	"strings"
	"unicode"
)

// 键值命令格式错误的原因（稳定标识符，帮助文档中有说明）。
const (
	ApplyReasonUnknownCommand   = `invalid command: expected "set <key>=<value>" or "delete <key>"`
	ApplyReasonEmptyKey         = "invalid command: key is empty"
	ApplyReasonKeyHasWhitespace = "invalid command: key contains whitespace"
	ApplyReasonKeyHasEquals     = "invalid command: key contains '='"
	ApplyReasonSetMissingEquals = "invalid command: set requires '=' between key and value"
	// incr 特有的三类失败：增量本身非法、当前值不是整数、相加溢出。
	ApplyReasonIncrMissingEquals = "invalid command: incr requires '=' between key and delta"
	ApplyReasonIncrBadDelta      = "invalid command: incr delta is not a signed 64-bit decimal integer"
	ApplyReasonIncrBadCurrent    = "invalid command: current value is not a signed 64-bit decimal integer"
	ApplyReasonIncrOverflow      = "invalid command: incr result exceeds signed 64-bit integer range"
)

// ApplyError 描述已提交命令中第一个格式错误：出错条目的日志索引与具体原因。
type ApplyError struct {
	Index  int    `json:"index"`
	Reason string `json:"reason"`
}

// kvOperation 是一条解析成功的键值命令。各动作共有的格式规则（等号分隔、键
// 校验）由 parseKVCommand 统一保证；各动作自己的参数含义与失败原因由各自的
// apply 方法保留，执行方不再区分动作种类。
type kvOperation struct {
	isDelete bool
	isIncr   bool
	key      string
	value    string // 仅 set 使用；按原文保留，允许为空
	delta    int64  // 仅 incr 使用；解析时已校验为有符号 64 位整数
}

// parseKVCommand 把一条命令解释为键值操作，失败时返回具体原因。
// 命令区分大小写，命令名后必须恰好有一个普通空格；键不能为空、不能含空白
// 或等号；set 与 incr 都以键后的第一个等号分隔参数：set 的值按原文保留
// （可为空、含空格、中文及额外等号），incr 的增量必须是有符号 64 位十进制
// 整数（允许负号与前导零，其余形式一律非法）。命令两端不做任何空白裁剪。
func parseKVCommand(command string) (kvOperation, string) {
	if rest, ok := strings.CutPrefix(command, "set "); ok {
		key, value, reason := splitKVPair(rest, ApplyReasonSetMissingEquals)
		if reason != "" {
			return kvOperation{}, reason
		}
		return kvOperation{key: key, value: value}, ""
	}
	if rest, ok := strings.CutPrefix(command, "delete "); ok {
		if reason := validateKVKey(rest); reason != "" {
			return kvOperation{}, reason
		}
		return kvOperation{isDelete: true, key: rest}, ""
	}
	if rest, ok := strings.CutPrefix(command, "incr "); ok {
		key, deltaText, reason := splitKVPair(rest, ApplyReasonIncrMissingEquals)
		if reason != "" {
			return kvOperation{}, reason
		}
		delta, ok := parseKVInt(deltaText)
		if !ok {
			return kvOperation{}, ApplyReasonIncrBadDelta
		}
		return kvOperation{isIncr: true, key: key, delta: delta}, ""
	}
	return kvOperation{}, ApplyReasonUnknownCommand
}

// splitKVPair 按键后的第一个等号把命令参数分成键与值，并校验键。缺少等号时
// 返回调用方给定的原因：写入与累加分别说明缺少值的分隔符或增量的分隔符，
// 等号分隔与键校验这套共有规则只在此维护一份。
func splitKVPair(rest, missingEquals string) (key, value, reason string) {
	eq := strings.IndexByte(rest, '=')
	if eq < 0 {
		return "", "", missingEquals
	}
	key, value = rest[:eq], rest[eq+1:]
	if reason := validateKVKey(key); reason != "" {
		return "", "", reason
	}
	return key, value, ""
}

// validateKVKey 校验键：不能为空、不能含空白或等号。
func validateKVKey(key string) string {
	if key == "" {
		return ApplyReasonEmptyKey
	}
	for _, r := range key {
		if unicode.IsSpace(r) {
			return ApplyReasonKeyHasWhitespace
		}
		if r == '=' {
			return ApplyReasonKeyHasEquals
		}
	}
	return ""
}

// parseKVInt 把字符串按有符号 64 位十进制整数解析：允许负号与前导零，
// 不接受正号、空白、小数、指数形式或非 ASCII 数字，空字符串也不是整数；
// 超出 int64 范围同样失败。先逐字节校验形状，再交给 strconv 判定范围。
func parseKVInt(s string) (int64, bool) {
	digits := s
	if strings.HasPrefix(digits, "-") {
		digits = digits[1:]
	}
	if digits == "" {
		return 0, false
	}
	for i := 0; i < len(digits); i++ {
		if digits[i] < '0' || digits[i] > '9' {
			return 0, false
		}
	}
	value, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		return 0, false
	}
	return value, true
}

// addKVInt 计算两个有符号 64 位整数之和，结果超出 int64 范围时 ok 为 false。
func addKVInt(a, b int64) (sum int64, ok bool) {
	sum = a + b
	// Go 的有符号溢出按二进制补码回绕：b 为正而和反而变小，或 b 为负而和
	// 反而变大，即越界。
	if (b > 0 && sum < a) || (b < 0 && sum > a) {
		return 0, false
	}
	return sum, true
}

// kvApplier 在本次调用内从空键值表开始，按日志索引顺序应用已提交命令。
// 一旦遇到格式错误，应用状态停住：已应用索引不再前进，错误保留到调用结束。
type kvApplier struct {
	kv           map[string]string
	appliedIndex int         // 已应用的最高日志索引，0 表示尚未应用任何条目
	err          *ApplyError // 非空后应用状态停住
}

func newKVApplier() *kvApplier {
	return &kvApplier{kv: map[string]string{}}
}

// applyUpTo 应用 (appliedIndex, committedIndex] 区间内尚未应用的已提交条目。
// 只前进不后退：空条目心跳、重复复制、提交位置不变时不会重复应用（incr 也
// 不会因此重复累加）；已出错时不再应用任何条目。未提交的条目不在此触及，
// 其格式错误不会提前暴露。
func (a *kvApplier) applyUpTo(log []LogEntry, committedIndex int) {
	if a.err != nil {
		return
	}
	for a.appliedIndex < committedIndex {
		next := a.appliedIndex + 1
		op, reason := parseKVCommand(log[next-1].Command)
		if reason == "" {
			reason = op.apply(a.kv)
		}
		if reason != "" {
			// 保留此前已成功应用的结果，已应用索引停在出错位置的前一条；
			// 本条命令不改变键值表。
			a.err = &ApplyError{Index: next, Reason: reason}
			return
		}
		a.appliedIndex = next
	}
}

// apply 把解析成功的操作作用到键值表，成功时返回空原因。各动作保留自己的
// 参数含义与失败原因：set 按原文写值，delete 删除（键不存在同样算成功），
// incr 按此前已生效的值累加。失败时键值表保持不变。
func (op kvOperation) apply(kv map[string]string) string {
	switch {
	case op.isDelete:
		delete(kv, op.key)
		return ""
	case op.isIncr:
		return op.applyIncr(kv)
	default:
		kv[op.key] = op.value
		return ""
	}
}

// applyIncr 计算一次增量后的新值并写回：键不存在时当前值按 0 处理（并因此
// 创建该键）；当前值必须是有符号 64 位十进制整数，相加结果也不得超出该范围。
// 成功时写回不带前导零的规范十进制形式（零统一为 "0"），增量为 0 同样写回
// 规范形式；失败时返回具体原因，键值表保持不变。
func (op kvOperation) applyIncr(kv map[string]string) string {
	current := int64(0)
	if existing, ok := kv[op.key]; ok {
		value, valid := parseKVInt(existing)
		if !valid {
			return ApplyReasonIncrBadCurrent
		}
		current = value
	}
	sum, ok := addKVInt(current, op.delta)
	if !ok {
		return ApplyReasonIncrOverflow
	}
	kv[op.key] = strconv.FormatInt(sum, 10)
	return ""
}

// 结果 JSON 中键值应用字段的编解码规则。逐条请求结果（AppendResult）与整次
// 调用结果（ReplicateOutput）两层共用本文件的同一套约定，避免两处各自实现
// 导致行为漂移。本文件只做纯逻辑处理。
package mevwatch

import (
	"bytes"
	"encoding/json"
)

// 两层结果共用的应用字段规则：
//
// 输出：是否输出应用字段由该层结果上的应用字段开关（applyFields）决定，
// 开关只在启用键值应用（ReplicateOptions.ApplyKV）的结果上打开。开关关闭
// 时应用字段整体缺省（字段上的 omitempty 生效，命令按任意字符串处理的原
// 有输出形状不变）；开关打开时该层全部应用字段强制输出，零值照常出现——
// 索引为 0 输出 0、空键值表输出 {}、无错误输出 null，不因值为空而省略。
//
// 填充：开启键值应用时，每条结果必须填已应用索引与应用错误，最终结果必须
// 填已应用索引、键值表与应用错误；没有复制请求时最终结果同样反映初始已
// 提交前缀的应用状态。
//
// 读入：按该层 JSON 中是否出现任一应用字段恢复开关，判定与解码接受的键名
// 规则一致：字段名只改字母大小写（如 "ApplyError"、"FINALKV"）也按出现处理，
// 与其值是否为空无关；与应用字段名只是相似的无关键不触发。出现任一字段即视
// 为启用应用的结果，再次输出时带上该层完整应用字段；完全未出现则不补上。
// 两层各自独立判断，互不推断。读入会用解码出的新值完整替换结果对象，不残留
// 上一次读入的键值表、应用位置或错误；JSON 无法解析或字段类型不合法照常返回
// 解码错误，结果对象保持读入前的内容，不会把错误内容当作零值接受。

// appendResultApplyKeys 是 AppendResult 一层用于判定应用字段是否出现的键名。
var appendResultApplyKeys = []string{"appliedIndex", "applyError"}

// replicateOutputApplyKeys 是 ReplicateOutput 一层用于判定应用字段是否出现的键名。
var replicateOutputApplyKeys = []string{"finalAppliedIndex", "finalKV", "finalApplyError"}

// marshalApplyFields 按开关选择输出形状：开关关闭时编码 plain（应用字段因
// omitempty 整体缺省）；开关打开时编码 forced（应用字段以零值兜底全部出现）。
func marshalApplyFields(plain any, applyFields bool, forced any) ([]byte, error) {
	if !applyFields {
		return json.Marshal(plain)
	}
	return json.Marshal(forced)
}

// unmarshalApplyFields 把 data 解码到 dst 指向的别名对象，并报告 data 中是否
// 出现 keys 里的任一应用字段键。解码成功时 *dst 被新值完整替换，不残留此前
// 读入的应用状态；JSON 无法解析或字段类型不合法时返回错误，*dst 保持不变。
func unmarshalApplyFields[T any](data []byte, dst *T, keys []string) (present bool, err error) {
	var decoded T
	if err := json.Unmarshal(data, &decoded); err != nil {
		return false, err
	}
	present, err = jsonHasAnyKey(data, keys...)
	if err != nil {
		return false, err
	}
	*dst = decoded
	return present, nil
}

// jsonHasAnyKey 报告 JSON 对象中是否出现任一给定键。判定与 encoding/json
// 解码时的字段匹配规则一致：键名比较按 Unicode 大小写折叠（等价于
// bytes.EqualFold），因此只改字母大小写的应用字段名（如 "ApplyError"）
// 同样算出现；与字段名只是相似的其他键不会命中。
func jsonHasAnyKey(data []byte, keys ...string) (bool, error) {
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return false, err
	}
	for presentKey := range raw {
		for _, key := range keys {
			if bytes.EqualFold([]byte(presentKey), []byte(key)) {
				return true, nil
			}
		}
	}
	return false, nil
}

// derefInt 返回指针指向的索引值，nil 按 0 处理（强制输出时的零值兜底）。
func derefInt(p *int) int {
	if p == nil {
		return 0
	}
	return *p
}

// nonNilStringMap 把 nil 键值表替换为空表，保证强制输出时得到 {} 而不是 null。
func nonNilStringMap(kv map[string]string) map[string]string {
	if kv == nil {
		return map[string]string{}
	}
	return kv
}

// setApplyFields 填充单条请求结果的应用字段并打开该层的应用字段开关：
// 处理本请求后已应用的最高日志索引与首个应用错误（无错误为 nil）。
func (r *AppendResult) setApplyFields(appliedIndex int, applyErr *ApplyError) {
	r.AppliedIndex = &appliedIndex
	r.ApplyError = applyErr
	r.applyFields = true
}

// setApplyFields 填充整次调用结果的应用字段并打开该层的应用字段开关：
// 最终已应用的最高日志索引、最终键值表与首个应用错误（无错误为 nil）。
func (o *ReplicateOutput) setApplyFields(appliedIndex int, kv map[string]string, applyErr *ApplyError) {
	o.FinalAppliedIndex = &appliedIndex
	o.FinalKV = kv
	o.FinalApplyError = applyErr
	o.applyFields = true
}

// MarshalJSON 按共用规则输出应用字段：未启用键值应用时保持原有输出形状；
// 启用时强制输出 appliedIndex 与 applyError（索引 0 照常出现，无错误时为 null）。
func (r AppendResult) MarshalJSON() ([]byte, error) {
	type alias AppendResult
	return marshalApplyFields(alias(r), r.applyFields, struct {
		alias
		AppliedIndex int         `json:"appliedIndex"`
		ApplyError   *ApplyError `json:"applyError"`
	}{
		alias:        alias(r),
		AppliedIndex: derefInt(r.AppliedIndex),
		ApplyError:   r.ApplyError,
	})
}

// UnmarshalJSON 按共用规则读入应用字段：出现 appendResultApplyKeys 中任一键
// （键名只改字母大小写也算，与解码的字段匹配规则一致）即视为启用键值应用的
// 结果，再次编码会原样保留这些字段（含 0、null）；未出现时按未启用处理。
// 整个对象被完整替换，不会残留上一次读入的应用状态。字段类型错误照常返回
// 解码错误，结果保持读入前的内容。
func (r *AppendResult) UnmarshalJSON(data []byte) error {
	type alias AppendResult
	var decoded alias
	present, err := unmarshalApplyFields(data, &decoded, appendResultApplyKeys)
	if err != nil {
		return err
	}
	*r = AppendResult(decoded)
	r.applyFields = present
	return nil
}

// MarshalJSON 按共用规则输出应用字段：未启用键值应用时保持原有输出形状；
// 启用时强制输出 finalAppliedIndex、finalKV（空表为 {}）与 finalApplyError
// （无错误为 null）。
func (o ReplicateOutput) MarshalJSON() ([]byte, error) {
	type alias ReplicateOutput
	return marshalApplyFields(alias(o), o.applyFields, struct {
		alias
		FinalAppliedIndex int               `json:"finalAppliedIndex"`
		FinalKV           map[string]string `json:"finalKV"`
		FinalApplyError   *ApplyError       `json:"finalApplyError"`
	}{
		alias:             alias(o),
		FinalAppliedIndex: derefInt(o.FinalAppliedIndex),
		FinalKV:           nonNilStringMap(o.FinalKV),
		FinalApplyError:   o.FinalApplyError,
	})
}

// UnmarshalJSON 按共用规则读入应用字段，语义同 AppendResult.UnmarshalJSON：
// 出现 replicateOutputApplyKeys 中任一键（键名只改字母大小写也算）时再次编码
// 保留 finalAppliedIndex、finalKV（空表为 {}）与 finalApplyError（无错误为
// null）；未出现时整个对象被完整替换，不残留上一次读入的键值表、错误或应用
// 位置。Results 中每条请求结果由 AppendResult.UnmarshalJSON 各自恢复。字段
// 类型错误照常返回解码错误，结果保持读入前的内容。
func (o *ReplicateOutput) UnmarshalJSON(data []byte) error {
	type alias ReplicateOutput
	var decoded alias
	present, err := unmarshalApplyFields(data, &decoded, replicateOutputApplyKeys)
	if err != nil {
		return err
	}
	*o = ReplicateOutput(decoded)
	o.applyFields = present
	return nil
}

