7	
8	// 本文件是“复制请求如何分批不改变同一段已提交日志最终生效结果”的回归保障：
9	// 从相同的合法初始状态出发，同一段日志（每条日志的索引、任期、命令及顺序完全
10	// 相同）无论是整段一次送达、分成多次连续请求送达，还是先复制再用空条目请求
11	// 推进提交，各次复制都能被接受，最终确认的日志范围、提交位置、应用位置、键值
12	// 表与首个应用错误都必须一致；中间提交位置只向前推进且不超过最终位置。逐条
13	// 请求的答复反映各自处理结束时的状态——分批方式不同，请求数量与提交时机自然
14	// 不同，这些答复不作逐项比较。
15	
16	// batchingInitial 是本文件回归场景共享的初始状态：当前任期 2，idx1
17	// （set count=10，任期 1）已提交，没有未提交尾部。后续所有送达方式都使用
18	// 相同的领导者任期 2。
19	func batchingInitial() InitialState {
20		return InitialState{CurrentTerm: 2, CommittedIndex: 1, Log: []LogEntry{
21			entry(1, 1, "set count=10"),
22		}}
23	}
24	
25	// batchDelivery 是同一段日志的一种送达方式：name 用于子测试，requests 为按序
26	// 到达的复制请求；wantCommits / wantApplied 是逐条请求处理结束时的提交位置与
27	// 应用位置（与 requests 一一对应）。
28	type batchDelivery struct {
29		name        string
30		requests    []AppendRequest
31		wantCommits []int
32		wantApplied []int
33	}
34	
35	// finalSummary 汇总一次调用结束时与分批方式无关的最终状态，用于跨方式比较。
36	type finalSummary struct {
37		term      int
38		committed int
39		log       []LogEntry
40		applied   int
41		kv        map[string]string
42		applyErr  *ApplyError
43	}
44	
45	func summarizeFinal(t *testing.T, out ReplicateOutput) finalSummary {
46		t.Helper()
47		if out.FinalAppliedIndex == nil || out.FinalKV == nil {
48			t.Fatalf("final apply fields missing in %+v", out)
49		}
50		return finalSummary{
51			term:      out.FinalTerm,
52			committed: out.FinalCommittedIndex,
53			log:       out.FinalLog,
54			applied:   *out.FinalAppliedIndex,
55			kv:        out.FinalKV,
56			applyErr:  out.FinalApplyError,
57		}
58	}
59	
60	// wantBatchingResults 断言每次复制都以 ok 接受、逐条答复的提交位置只向前推进
61	// 且不超过最终位置，并与期望的逐条提交位置、应用位置一致。
62	func wantBatchingResults(t *testing.T, delivery batchDelivery, out ReplicateOutput, initialCommit int) {
63		t.Helper()
64		if len(out.Results) != len(delivery.requests) {
65			t.Fatalf("got %d results, want %d", len(out.Results), len(delivery.requests))
66		}
67		previous := initialCommit
68		for i, result := range out.Results {
69			if !result.Accepted || result.Reason != ReasonOK {
70				t.Fatalf("result %d must be accepted with reason ok, got %+v", i, result)
71			}
72			if result.Term != 2 {
73				t.Fatalf("result %d term = %d, want 2", i, result.Term)
74			}
75			if result.CommittedIndex < previous {
76				t.Fatalf("result %d committedIndex moved backward: %d < %d",
77					i, result.CommittedIndex, previous)
78			}
79			if result.CommittedIndex > out.FinalCommittedIndex {
80				t.Fatalf("result %d committedIndex %d exceeds final %d",
81					i, result.CommittedIndex, out.FinalCommittedIndex)
82			}
83			if result.CommittedIndex != delivery.wantCommits[i] {
84				t.Fatalf("result %d committedIndex = %d, want %d",
85					i, result.CommittedIndex, delivery.wantCommits[i])
86			}
87			if got := appliedIndexOf(t, result); got != delivery.wantApplied[i] {
88				t.Fatalf("result %d appliedIndex = %d, want %d", i, got, delivery.wantApplied[i])
89			}
90			previous = result.CommittedIndex
91		}
92	}
93	
94	// batchingIncrEntries 是场景一共享的日志段：两次依赖先前值的累加，加一条最终
95	// 提交范围以外的写入。三条日志的索引、任期、命令及顺序在所有送达方式中相同。
96	func batchingIncrEntries() []LogEntry {
97		return []LogEntry{
98			entry(2, 2, "incr count=5"),
99			entry(3, 2, "incr count=-2"),
100			entry(4, 2, "set extra=late"), // 最终提交范围以外：保留在日志中但不生效
101		}
102	}
103	
104	// batchingIncrDeliveries 是场景一的各种送达方式：整段一次送达、在两次累加之间
105	// 切分、逐条送达、先复制再用空条目请求推进提交。最终提交位置都是 3。
106	func batchingIncrDeliveries() []batchDelivery {
107		entries := batchingIncrEntries()
108		return []batchDelivery{
109			{
110				"whole segment in one request",
111				[]AppendRequest{
112					{Term: 2, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 3, Entries: entries},
113				},
114				[]int{3},
115				[]int{3},
116			},
117			{
118				"split between the two increments",
119				[]AppendRequest{
120					{Term: 2, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 2, Entries: entries[:1]},
121					{Term: 2, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 3, Entries: entries[1:]},
122				},
123				[]int{2, 3},
124				[]int{2, 3},
125			},
126			{
127				"one request per entry",
128				[]AppendRequest{
129					{Term: 2, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 2, Entries: entries[:1]},
130					{Term: 2, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 3, Entries: entries[1:2]},
131					{Term: 2, PrevLogIndex: 3, PrevLogTerm: 2, LeaderCommit: 3, Entries: entries[2:]},
132				},
133				[]int{2, 3, 3},
134				[]int{2, 3, 3},
135			},
136			{
137				"replicate first then commit via heartbeat",
138				[]AppendRequest{
139					{Term: 2, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 1, Entries: entries},
140					{Term: 2, PrevLogIndex: 4, PrevLogTerm: 2, LeaderCommit: 3},
141				},
142				[]int{1, 3},
143				[]int{1, 3},
144			},
145		}
146	}
147	
148	// TestBatchingDoesNotChangeFinalIncrOutcome 场景一：初始已提交日志把 count 设为
149	// 字符串 "10"，随后依次提交 incr count=5 与 incr count=-2。无论整段一次送达、
150	// 在两次累加之间切分、逐条送达，还是复制完成后才用空条目请求提交，最终日志、
151	// 任期、提交位置、应用位置、键值表与首个应用错误都必须一致：count 最终为
152	// "13"（不漏加、不重复累加、不重新写回初始值），应用位置到达最后一条已提交
153	// 日志 idx3；idx4 的写入在最终提交范围以外，保留在完整日志中但不影响键值表。
154	func TestBatchingDoesNotChangeFinalIncrOutcome(t *testing.T) {
155		wantLog := append([]LogEntry{entry(1, 1, "set count=10")}, batchingIncrEntries()...)
156		var baseline *finalSummary
157		for _, delivery := range batchingIncrDeliveries() {
158			t.Run(delivery.name, func(t *testing.T) {
159				out := runKV(t, batchingInitial(), delivery.requests...)
160				wantBatchingResults(t, delivery, out, 1)
161				for i, result := range out.Results {
162					if result.ApplyError != nil {
163						t.Fatalf("result %d unexpected apply error: %+v", i, result.ApplyError)
164					}
165				}
166	
167				if !reflect.DeepEqual(out.FinalLog, wantLog) {
168					t.Fatalf("final log = %+v, want %+v", out.FinalLog, wantLog)
169				}
170				if out.FinalTerm != 2 || out.FinalCommittedIndex != 3 {
171					t.Fatalf("final state = term %d ci %d, want term 2 ci 3",
172						out.FinalTerm, out.FinalCommittedIndex)
173				}
174				if *out.FinalAppliedIndex != 3 {
175					t.Fatalf("final appliedIndex = %d, want 3 (last committed entry)",
176						*out.FinalAppliedIndex)
177				}
178				kv := finalKVOf(t, out)
179				if !reflect.DeepEqual(kv, map[string]string{"count": "13"}) {
180					t.Fatalf("final kv = %v, want only count=13", kv)
181				}
182				if _, ok := kv["extra"]; ok {
183					t.Fatalf("uncommitted entry idx4 took effect: %v", kv)
184				}
185				if out.FinalApplyError != nil {
186					t.Fatalf("final apply error = %+v, want none", out.FinalApplyError)
187				}
188	
189				// 与第一种送达方式比较最终状态：分批方式不得改变最终生效结果。
190				summary := summarizeFinal(t, out)
191				if baseline == nil {
192					baseline = &summary
193				} else if !reflect.DeepEqual(summary, *baseline) {
194					t.Fatalf("final state differs across deliveries:\n got %+v\nwant %+v",
195						summary, *baseline)
196				}
197			})
198		}
199	}
200	
201	// batchingIllegalIncrEntries 是场景二共享的日志段：两次合法累加之后接一条非法
202	// 增量，再接一条合法写入。四条日志的索引、任期、命令及顺序在所有送达方式中相同。
203	func batchingIllegalIncrEntries() []LogEntry {
204		return []LogEntry{
205			entry(2, 2, "incr count=5"),
206			entry(3, 2, "incr count=-2"),
207			entry(4, 2, "incr count=oops"), // 非法增量：提交后应用停在其前
208			entry(5, 2, "set receipt=ok"),  // 错误之后的合法写入：不能生效
209		}
210	}
211	
212	// batchingIllegalIncrDeliveries 是场景二的各种送达方式：非法条目与前后条目同
213	// 在一个请求、独占一个请求，或先全部复制再用空条目请求逐步推进提交。最终提交
214	// 位置都是 5。
215	func batchingIllegalIncrDeliveries() []batchDelivery {
216		entries := batchingIllegalIncrEntries()
217		return []batchDelivery{
218			{
219				"whole segment in one request",
220				[]AppendRequest{
221					{Term: 2, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 5, Entries: entries},
222				},
223				[]int{5},
224				[]int{3},
225			},
226			{
227				"illegal entry shares a request with its neighbors",
228				[]AppendRequest{
229					{Term: 2, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 3, Entries: entries[:2]},
230					{Term: 2, PrevLogIndex: 3, PrevLogTerm: 2, LeaderCommit: 5, Entries: entries[2:]},
231				},
232				[]int{3, 5},
233				[]int{3, 3},
234			},
235			{
236				"illegal entry in its own request",
237				[]AppendRequest{
238					{Term: 2, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 3, Entries: entries[:2]},
239					{Term: 2, PrevLogIndex: 3, PrevLogTerm: 2, LeaderCommit: 4, Entries: entries[2:3]},
240					{Term: 2, PrevLogIndex: 4, PrevLogTerm: 2, LeaderCommit: 5, Entries: entries[3:]},
241				},
242				[]int{3, 4, 5},
243				[]int{3, 3, 3},
244			},
245			{
246				"replicate first then commit via heartbeats",
247				[]AppendRequest{
248					{Term: 2, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 1, Entries: entries},
249					{Term: 2, PrevLogIndex: 5, PrevLogTerm: 2, LeaderCommit: 4},
250					{Term: 2, PrevLogIndex: 5, PrevLogTerm: 2, LeaderCommit: 5},
251				},
252				[]int{1, 4, 5},
253				[]int{1, 3, 3},
254			},
255		}
256	}
257	
258	// TestBatchingCommittedIllegalIncrOutcomeIsBatchingIndependent 场景二：遇到已提交
259	// 的非法增量时，分批一致性同样成立。无论非法命令与前后条目是否处于同一个请求，
260	// 最终都保留 count 的 "13"，应用位置停在非法条目之前（idx3），首个应用错误指向
261	// idx4 并报告现有的增量格式错误，idx5 的合法写入不能生效；完整日志与提交位置
262	// 不受应用停滞影响。逐条答复中，应用错误只能在非法条目提交之后出现。
263	func TestBatchingCommittedIllegalIncrOutcomeIsBatchingIndependent(t *testing.T) {
264		wantLog := append([]LogEntry{entry(1, 1, "set count=10")}, batchingIllegalIncrEntries()...)
265		wantErr := &ApplyError{Index: 4, Reason: ApplyReasonIncrBadDelta}
266		var baseline *finalSummary
267		for _, delivery := range batchingIllegalIncrDeliveries() {
268			t.Run(delivery.name, func(t *testing.T) {
269				out := runKV(t, batchingInitial(), delivery.requests...)
270				wantBatchingResults(t, delivery, out, 1)
271				// 非法条目 idx4 尚未提交时不提前产生应用错误；提交它以后错误出现，
272				// 且后续合法复制仍被接受、提交位置继续推进。
273				for i, result := range out.Results {
274					switch {
275					case result.CommittedIndex >= 4:
276						if result.ApplyError == nil || *result.ApplyError != *wantErr {
277							t.Fatalf("result %d applyError = %+v, want %+v", i, result.ApplyError, wantErr)
278						}
279					default:
280						if result.ApplyError != nil {
281							t.Fatalf("result %d reported error before idx4 was committed: %+v",
282								i, result.ApplyError)
283						}
284					}
285				}
286	
287				if !reflect.DeepEqual(out.FinalLog, wantLog) {
288					t.Fatalf("final log = %+v, want %+v", out.FinalLog, wantLog)
289				}
290				if out.FinalTerm != 2 || out.FinalCommittedIndex != 5 {
291					t.Fatalf("final state = term %d ci %d, want term 2 ci 5",
292						out.FinalTerm, out.FinalCommittedIndex)
293				}
294				if *out.FinalAppliedIndex != 3 {
295					t.Fatalf("final appliedIndex = %d, want 3 (stops before the illegal entry)",
296						*out.FinalAppliedIndex)
297				}
298				kv := finalKVOf(t, out)
299				if !reflect.DeepEqual(kv, map[string]string{"count": "13"}) {
300					t.Fatalf("final kv = %v, want only count=13", kv)
301				}
302				if _, ok := kv["receipt"]; ok {
303					t.Fatalf("write after the illegal entry took effect: %v", kv)
304				}
305				if out.FinalApplyError == nil || *out.FinalApplyError != *wantErr {
306					t.Fatalf("final applyError = %+v, want %+v", out.FinalApplyError, wantErr)
307				}
308	
309				// 与第一种送达方式比较最终状态：非法条目如何分批不改变最终结果。
310				summary := summarizeFinal(t, out)
311				if baseline == nil {
312					baseline = &summary
313				} else if !reflect.DeepEqual(summary, *baseline) {
314					t.Fatalf("final state differs across deliveries:\n got %+v\nwant %+v",
315						summary, *baseline)
316				}
317			})
318		}
319	}
320	
321	// TestBatchingApplyStallIsNotReplicationRejection 回归保障：非法增量提交后应用
322	// 停滞，但复制本身不因此转为拒绝。先整段复制（未提交，无应用错误），再用空条目
323	// 心跳把提交推进到非法条目（错误出现、应用停在 idx3），之后合法复制仍被接受并
324	// 继续推进提交位置——包括纯心跳推进与追加新条目，应用位置与已报告的错误保持
325	// 不变，错误之后的写入不生效。
326	func TestBatchingApplyStallIsNotReplicationRejection(t *testing.T) {
327		entries := batchingIllegalIncrEntries()
328		out := runKV(t, batchingInitial(),
329			// 整段复制，暂不提交：非法条目未提交，不产生应用错误。
330			AppendRequest{Term: 2, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 1, Entries: entries},
331			// 空条目心跳把提交推进到 idx4：非法增量此时才报告，应用停在 idx3。
332			AppendRequest{Term: 2, PrevLogIndex: 5, PrevLogTerm: 2, LeaderCommit: 4},
333			// 应用已停滞，后续合法复制仍被接受：心跳推进提交到 idx5。
334			AppendRequest{Term: 2, PrevLogIndex: 5, PrevLogTerm: 2, LeaderCommit: 5},
335			// 追加新条目并提交：复制照常接受，错误之后的写入仍不生效。
336			AppendRequest{Term: 2, PrevLogIndex: 5, PrevLogTerm: 2, LeaderCommit: 6,
337				Entries: []LogEntry{entry(6, 2, "set later=nope")}},
338		)
339	
340		wantCommits := []int{1, 4, 5, 6}
341		wantApplied := []int{1, 3, 3, 3}
342		wantErr := &ApplyError{Index: 4, Reason: ApplyReasonIncrBadDelta}
343		if len(out.Results) != 4 {
344			t.Fatalf("got %d results, want 4", len(out.Results))
345		}
346		for i, result := range out.Results {
347			if !result.Accepted || result.Reason != ReasonOK {
348				t.Fatalf("result %d must stay accepted despite the apply stall: %+v", i, result)
349			}
350			if result.CommittedIndex != wantCommits[i] {
351				t.Fatalf("result %d committedIndex = %d, want %d", i, result.CommittedIndex, wantCommits[i])
352			}
353			if got := appliedIndexOf(t, result); got != wantApplied[i] {
354				t.Fatalf("result %d appliedIndex = %d, want %d", i, got, wantApplied[i])
355			}
356			if i == 0 {
357				if result.ApplyError != nil {
358					t.Fatalf("uncommitted illegal entry reported early: %+v", result.ApplyError)
359				}
360			} else if result.ApplyError == nil || *result.ApplyError != *wantErr {
361				t.Fatalf("result %d applyError = %+v, want %+v", i, result.ApplyError, wantErr)
362			}
363		}
364	
365		wantLog := append(append([]LogEntry{entry(1, 1, "set count=10")}, batchingIllegalIncrEntries()...),
366			entry(6, 2, "set later=nope"))
367		if !reflect.DeepEqual(out.FinalLog, wantLog) {
368			t.Fatalf("final log = %+v, want %+v", out.FinalLog, wantLog)
369		}
370		if out.FinalTerm != 2 || out.FinalCommittedIndex != 6 {
371			t.Fatalf("final state = term %d ci %d, want term 2 ci 6",
372				out.FinalTerm, out.FinalCommittedIndex)
373		}
374		if *out.FinalAppliedIndex != 3 {
375			t.Fatalf("final appliedIndex = %d, want 3", *out.FinalAppliedIndex)
376		}
377		kv := finalKVOf(t, out)
378		if !reflect.DeepEqual(kv, map[string]string{"count": "13"}) {
379			t.Fatalf("final kv = %v, want only count=13", kv)
380		}
381		if out.FinalApplyError == nil || *out.FinalApplyError != *wantErr {
382			t.Fatalf("final applyError = %+v, want %+v", out.FinalApplyError, wantErr)
383		}
384	}
