744				// 首条任期 1 仍低于声明值：仍是同一条字段错误，不能改成前置日志
745				// 不匹配，也不能留下较高任期更新。
746				"declared prev term mismatches local too",
747				AppendRequest{Term: 7, PrevLogIndex: 2, PrevLogTerm: 5, LeaderCommit: 9,
748					Entries: []LogEntry{entry(3, 1, "x")}},
749			},
