760				"first term one below declared prev term",
761				AppendRequest{Term: 7, PrevLogIndex: 2, PrevLogTerm: 3, LeaderCommit: 4,
762					Entries: []LogEntry{entry(3, 2, "x")}},
763			},
764			{
