769					Entries: []LogEntry{entry(3, 1, "x"), entry(4, 7, "y")}},
770			},
771		}
772		for _, tc := range cases {
773			t.Run(tc.name, func(t *testing.T) {
774				out := run(t, initial, tc.request)
775				result := out.Results[0]
776				if result.Accepted {
777					t.Fatalf("request should be rejected: %+v", result)
778				}
779				if result.Reason != ReasonEntryTermDecreases {
780					t.Fatalf("reason = %q, want exact %q", result.Reason, ReasonEntryTermDecreases)
781				}
782				if !strings.Contains(result.Reason, "entry terms are not non-decreasing") {
783					t.Fatalf("reason text changed: %q", result.Reason)
784				}
785				if result.Conflict != nil {
786					t.Fatalf("field error must not be treated as a replication conflict: %+v", result.Conflict)
787				}
788				if result.Term != 2 {
789					t.Fatalf("higher term must not survive a field error, term = %d, want 2", result.Term)
790				}
791				if result.CommittedIndex != 1 {
792					t.Fatalf("commit changed: %d, want 1", result.CommittedIndex)
793				}
794				if out.FinalTerm != 2 || out.FinalCommittedIndex != 1 {
795					t.Fatalf("final state changed: term=%d ci=%d", out.FinalTerm, out.FinalCommittedIndex)
796				}
797				if !reflect.DeepEqual(out.FinalLog, original) {
798					t.Fatalf("log changed: %+v", out.FinalLog)
799				}
800				// 输出约定：该拒绝的 JSON 中不出现 conflict 键。
801				encoded, err := json.Marshal(result)
802				if err != nil {
803					t.Fatal(err)
804				}
805				if strings.Contains(string(encoded), "conflict") {
806					t.Fatalf("rejection JSON must omit conflict: %s", encoded)
807				}
808			})
809		}
810	}
811	
812	// TestFirstEntryTermEqualPrevLogTermIsLegal 首条任期恰好等于前置任期是合法衔接，
813	// 包括领导者任期更高、首条沿用旧任期的情形。
814	func TestFirstEntryTermEqualPrevLogTermIsLegal(t *testing.T) {
815		initial := InitialState{CurrentTerm: 2, CommittedIndex: 1, Log: []LogEntry{
816			entry(1, 1, "a"), entry(2, 2, "b"),
817		}}
818		out := run(t, initial,
819			// 同任期追加：首条任期 2 == 前置任期 2。
820			AppendRequest{Term: 2, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 3,
821				Entries: []LogEntry{entry(3, 2, "c")}},
822		)
823		if !out.Results[0].Accepted || out.Results[0].Reason != ReasonOK {
824			t.Fatalf("equal-term bridge should be accepted: %+v", out.Results[0])
825		}
826	
827		// 更高任期的领导者携带一条旧任期条目：首条任期 2 仍等于前置任期 2，
828		// 合法；随后条目任期升到 3 同样合法。
829		out = run(t, initial,
830			AppendRequest{Term: 3, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 4,
831				Entries: []LogEntry{entry(3, 2, "c"), entry(4, 3, "d")}},
832		)
833		result := out.Results[0]
834		if !result.Accepted || result.Reason != ReasonOK {
835			t.Fatalf("equal-term bridge under higher leader term should be accepted: %+v", result)
836		}
837		want := []LogEntry{
838			entry(1, 1, "a"), entry(2, 2, "b"), entry(3, 2, "c"), entry(4, 3, "d"),
839		}
840		if !reflect.DeepEqual(out.FinalLog, want) {
841			t.Fatalf("log = %+v, want %+v", out.FinalLog, want)
842		}
843		if result.Term != 3 || result.CommittedIndex != 4 {
844			t.Fatalf("state = term %d ci %d, want term 3 ci 4", result.Term, result.CommittedIndex)
845		}
846	}
847	
848	// TestEmptyEntriesHaveNoFirstTermBridge 空条目请求没有首条日志，不能因此报任期
849	// 下降：前置不匹配时仍按前置日志不匹配拒绝、附带 conflict 并保留较高任期更新；
850	// 前置匹配时就是正常心跳。
851	func TestEmptyEntriesHaveNoFirstTermBridge(t *testing.T) {
852		initial := InitialState{CurrentTerm: 2, CommittedIndex: 1, Log: []LogEntry{
853			entry(1, 1, "a"), entry(2, 2, "b"),
854		}}
855		out := run(t, initial,
856			// 前置任期与本地不一致：拒绝原因是前置不匹配，不是条目任期下降。
857			AppendRequest{Term: 7, PrevLogIndex: 2, PrevLogTerm: 5, LeaderCommit: 9},
858			// 前置索引越过日志末尾：同样是前置不匹配。
859			AppendRequest{Term: 8, PrevLogIndex: 5, PrevLogTerm: 3},
860			// 前置匹配的空条目心跳：接受，leaderCommit 再大也只确认到前置索引。
861			AppendRequest{Term: 8, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 9},
862		)
863		first := out.Results[0]
864		if first.Accepted || first.Reason != ReasonPrevLogMismatch {
865			t.Fatalf("empty request should be a prev mismatch, got %+v", first)
866		}
867		if first.Term != 7 {
868			t.Fatalf("higher term should survive mismatch, term = %d, want 7", first.Term)
869		}
870		if first.Conflict == nil || *first.Conflict != (ConflictHint{Index: 2, Term: 2}) {
871			t.Fatalf("conflict = %+v, want {2 2}", first.Conflict)
872		}
873		second := out.Results[1]
874		if second.Accepted || second.Reason != ReasonPrevLogMismatch {
875			t.Fatalf("beyond-end empty request should be a prev mismatch, got %+v", second)
876		}
877		if second.Conflict == nil || *second.Conflict != (ConflictHint{Index: 3, Term: 0}) {
878			t.Fatalf("conflict = %+v, want {3 0}", second.Conflict)
879		}
880		heartbeat := out.Results[2]
881		if !heartbeat.Accepted || heartbeat.Reason != ReasonOK {
882			t.Fatalf("matching heartbeat should be accepted: %+v", heartbeat)
883		}
884		if heartbeat.CommittedIndex != 2 {
885			t.Fatalf("heartbeat confirmed only index 2, commit = %d, want 2", heartbeat.CommittedIndex)
886		}
887		if len(out.FinalLog) != 2 {
888			t.Fatalf("heartbeat must not change the log: %+v", out.FinalLog)
889		}
890	}
891	
892	// TestStaleTermPrecedesFirstTermBridge 低任期请求沿用现有的拒绝顺序：即使它同时
893	// 满足“首条任期低于前置任期”，拒绝原因仍是低任期，且不附带 conflict。
894	func TestStaleTermPrecedesFirstTermBridge(t *testing.T) {
895		initial := InitialState{CurrentTerm: 2, CommittedIndex: 1, Log: []LogEntry{
896			entry(1, 1, "a"), entry(2, 2, "b"),
897		}}
898		out := run(t, initial,
899			AppendRequest{Term: 1, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 3,
900				Entries: []LogEntry{entry(3, 1, "c")}},
901		)
902		result := out.Results[0]
903		if result.Accepted || result.Reason != ReasonStaleTerm {
904			t.Fatalf("expected stale-term rejection, got %+v", result)
905		}
906		if result.Conflict != nil {
907			t.Fatalf("stale-term rejection must not carry conflict: %+v", result.Conflict)
908		}
909		if result.Term != 2 || result.CommittedIndex != 1 {
910			t.Fatalf("state changed: %+v", result)
911		}
912		if !reflect.DeepEqual(out.FinalLog, initial.Log) {
913			t.Fatalf("log changed: %+v", out.FinalLog)
914		}
915	}
916	
917	// TestFirstEntryTermBridgeFieldErrorThenValidRecovery 非法衔接请求被拒后节点保持
918	// 原状态，随后到达的合法请求按原状态继续处理：任期 3、正确匹配索引 2，追加索引
919	// 3、任期 2 的条目并提交到 3。
920	func TestFirstEntryTermBridgeFieldErrorThenValidRecovery(t *testing.T) {
921		initial := InitialState{CurrentTerm: 2, CommittedIndex: 1, Log: []LogEntry{
922			entry(1, 1, "set balance=100"),
923			entry(2, 2, "set balance=200"),
924		}}
925		bad := AppendRequest{Term: 7, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 9,
926			Entries: []LogEntry{entry(3, 1, "set evil=1")}}
927		legal := AppendRequest{Term: 3, PrevLogIndex: 2, PrevLogTerm: 2, LeaderCommit: 3,
928			Entries: []LogEntry{entry(3, 2, "set receipt=ok")}}
929		out := run(t, initial, bad, legal)
930	
931		first := out.Results[0]
932		if first.Accepted || first.Reason != ReasonEntryTermDecreases {
933			t.Fatalf("first request should be the term-bridge field error, got %+v", first)
934		}
935		if first.Conflict != nil || first.Term != 2 || first.CommittedIndex != 1 {
936			t.Fatalf("first request changed state: %+v", first)
937		}
938		second := out.Results[1]
939		if !second.Accepted || second.Reason != ReasonOK {
940			t.Fatalf("valid follow-up request must be processed from the original state: %+v", second)
941		}
942		if second.Term != 3 || second.CommittedIndex != 3 {
943			t.Fatalf("second result state = term %d ci %d, want term 3 ci 3",
944				second.Term, second.CommittedIndex)
945		}
946		want := []LogEntry{
947			entry(1, 1, "set balance=100"),
948			entry(2, 2, "set balance=200"),
949			entry(3, 2, "set receipt=ok"),
950		}
951		if !reflect.DeepEqual(out.FinalLog, want) {
952			t.Fatalf("final log = %+v, want %+v", out.FinalLog, want)
953		}
954		if out.FinalTerm != 3 || out.FinalCommittedIndex != 3 {
955			t.Fatalf("final state = term %d ci %d, want term 3 ci 3",
956				out.FinalTerm, out.FinalCommittedIndex)
957		}
958	}
959	
960	// conflict 只在前置日志不匹配的结果里出现在 JSON 中，其余结果不输出该键。
961	func TestConflictHintJSONShape(t *testing.T) {
962		out := run(t, InitialState{CurrentTerm: 2, Log: []LogEntry{entry(1, 2, "a")}},
963			AppendRequest{Term: 2, PrevLogIndex: 1, PrevLogTerm: 2},
964			AppendRequest{Term: 2, PrevLogIndex: 3, PrevLogTerm: 2},
965		)
966		encoded, err := json.Marshal(out.Results[0])
967		if err != nil {
968			t.Fatal(err)
969		}
970		if strings.Contains(string(encoded), "conflict") {
971			t.Fatalf("accepted result should omit conflict, got %s", encoded)
972		}
973		encoded, err = json.Marshal(out.Results[1])
974		if err != nil {
975			t.Fatal(err)
976		}
977		var decoded map[string]any
978		if err := json.Unmarshal(encoded, &decoded); err != nil {
979			t.Fatal(err)
980		}
981		conflict, ok := decoded["conflict"].(map[string]any)
982		if !ok {
983			t.Fatalf("mismatch result should carry conflict object, got %s", encoded)
984		}
985		if conflict["index"] != float64(2) || conflict["term"] != float64(0) {
986			t.Fatalf("conflict = %v, want index 2 term 0", conflict)
987		}
988		// 编解码往返后反馈保持原样。
989		var roundTrip AppendResult
990		if err := json.Unmarshal(encoded, &roundTrip); err != nil {
991			t.Fatal(err)
992		}
993		if roundTrip.Conflict == nil || *roundTrip.Conflict != (ConflictHint{Index: 2, Term: 0}) {
994			t.Fatalf("round trip conflict = %+v, want {2 0}", roundTrip.Conflict)
995		}
996	}
