1	package mevwatch
2	
3	import (
4		"encoding/json"
5		"math"
6		"reflect"
7		"strconv"
8		"strings"
9		"testing"
10	)
11	
12	// incrSuffixConflictInitial 是任期冲突替换回归场景共享的初始状态：当前任期 2，
13	// 索引 1..3 的任期均为 1；只有 idx1（incr count=10）已提交，计数因此为 "10"。
14	// idx2（incr count=100）与 idx3（incr count=1.5，增量不是整数）构成未提交旧
15	// 后缀：它们既不能提前累加，也不能提前暴露 idx3 的非法增量；后续被整段替换时
16	// 两条都必须从最终日志消失，且不在键值表留下任何效果。
17	func incrSuffixConflictInitial() InitialState {
18		return InitialState{CurrentTerm: 2, CommittedIndex: 1, Log: []LogEntry{
19			entry(1, 1, "incr count=10"),
20			entry(2, 1, "incr count=100"),
21			entry(3, 1, "incr count=1.5"),
22		}}
23	}
