25	// TestKVIncrTermConflictReplacesUncommittedIncrSuffix 回归保障任务主场景：
26	// 已提交的 incr count=10 使计数为 "10"，未提交后缀另有合法增量 incr count=100
27	// 与非法增量 incr count=1.5。后续请求匹配前置日志 idx1，并在未提交起点 idx2
28	// 带来不同任期的条目（旧任期 1、新任期 2），只携带一条 incr count=-3 并将其
29	// 提交。旧冲突位置及其后的日志必须被新内容整段替换：
30	//   - 请求正常接受（reason ok），提交位置与应用位置都推进到 2；
31	//   - 最终日志只剩原已提交前缀 idx1 与新条目 idx2，incr count=100 与
32	//     incr count=1.5 均从最终日志消失；
33	//   - 已生效的前缀不能重新累加，被丢弃的合法增量 100 也不能影响计数：
34	//     最终计数为 10 + (-3) = "7"，键值表只有 count 一个键，无应用错误。
35	func TestKVIncrTermConflictReplacesUncommittedIncrSuffix(t *testing.T) {
36		initial := incrSuffixConflictInitial()
37	
38		// 起点：只有初始已提交前缀生效，未提交后缀既不累加也不暴露格式错误。
39		start := runKV(t, initial)
40		if *start.FinalAppliedIndex != 1 {
41			t.Fatalf("initial appliedIndex = %d, want 1", *start.FinalAppliedIndex)
42		}
43		if !reflect.DeepEqual(finalKVOf(t, start), map[string]string{"count": "10"}) {
44			t.Fatalf("initial kv = %v, want only count=10", start.FinalKV)
45		}
46		if start.FinalApplyError != nil {
47			t.Fatalf("uncommitted bad incr reported early: %+v", start.FinalApplyError)
48		}
49		if len(start.FinalLog) != 3 {
50			t.Fatalf("initial log = %d entries, want 3", len(start.FinalLog))
51		}
52	
53		out := runKV(t, initial,
54			AppendRequest{Term: 2, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 2,
55				Entries: []LogEntry{entry(2, 2, "incr count=-3")}},
56		)
57		if len(out.Results) != 1 {
58			t.Fatalf("got %d results, want 1", len(out.Results))
59		}
60		result := out.Results[0]
61		if !result.Accepted || result.Reason != ReasonOK {
62			t.Fatalf("different-term replacement should be accepted: %+v", result)
63		}
64		if result.Conflict != nil {
65			t.Fatalf("accepted replacement must not carry a conflict hint: %+v", result.Conflict)
66		}
67		if result.Term != 2 || result.CommittedIndex != 2 {
68			t.Fatalf("result state = term %d ci %d, want term 2 ci 2",
69				result.Term, result.CommittedIndex)
70		}
71		if got := appliedIndexOf(t, result); got != 2 {
72			t.Fatalf("result appliedIndex = %d, want 2 (new entry took effect)", got)
73		}
74		if result.ApplyError != nil {
75			t.Fatalf("replacement incr must apply cleanly: %+v", result.ApplyError)
76		}
77	
78		wantLog := []LogEntry{
79			entry(1, 1, "incr count=10"),
80			entry(2, 2, "incr count=-3"),
81		}
82		if !reflect.DeepEqual(out.FinalLog, wantLog) {
83			t.Fatalf("final log = %+v, want %+v (old suffix must vanish)", out.FinalLog, wantLog)
84		}
85		if out.FinalTerm != 2 || out.FinalCommittedIndex != 2 {
86			t.Fatalf("final state = term %d ci %d, want term 2 ci 2",
87				out.FinalTerm, out.FinalCommittedIndex)
88		}
89		if *out.FinalAppliedIndex != 2 {
90			t.Fatalf("final appliedIndex = %d, want 2", *out.FinalAppliedIndex)
91		}
92		if kv := finalKVOf(t, out); !reflect.DeepEqual(kv, map[string]string{"count": "7"}) {
93			t.Fatalf("final kv = %v, want only count=7 (prefix kept, discarded incr ignored)", kv)
94		}
95		if out.FinalApplyError != nil {
96			t.Fatalf("final apply error = %+v, want none", out.FinalApplyError)
97		}
98	}
