100	// TestKVIncrConflictReplacementPerRequestState 回归保障每条请求结果只保留处理
101	// 当时的接受状态、任期、提交与应用位置：先到的空条目心跳不确认未提交后缀
102	// （计数停在 "10"、提交与应用位置停在 1），随后的不同任期替换把 idx2 换成
103	// incr count=-3 并提交，第二条结果才反映提交/应用位置 2 与计数 "7"；第一条
104	// 结果不被后续状态覆盖。
105	func TestKVIncrConflictReplacementPerRequestState(t *testing.T) {
106		out := runKV(t, incrSuffixConflictInitial(),
107			// 心跳匹配到 idx3 但不推进提交：未提交后缀不能借此生效。
108			AppendRequest{Term: 2, PrevLogIndex: 3, PrevLogTerm: 1, LeaderCommit: 0},
109			// 从后缀起点以任期 2 替换 idx2 并提交到 2。
110			AppendRequest{Term: 2, PrevLogIndex: 1, PrevLogTerm: 1, LeaderCommit: 2,
111				Entries: []LogEntry{entry(2, 2, "incr count=-3")}},
112		)
113		first := out.Results[0]
114		if !first.Accepted || first.Reason != ReasonOK {
115			t.Fatalf("heartbeat should be accepted: %+v", first)
116		}
117		if first.CommittedIndex != 1 || appliedIndexOf(t, first) != 1 {
118			t.Fatalf("first result must keep point-in-time state ci %d applied %d, want 1/1",
119				first.CommittedIndex, *first.AppliedIndex)
120		}
121		if first.ApplyError != nil {
122			t.Fatalf("heartbeat must not surface uncommitted bad incr: %+v", first.ApplyError)
123		}
124		second := out.Results[1]
125		if !second.Accepted || second.CommittedIndex != 2 || appliedIndexOf(t, second) != 2 {
126			t.Fatalf("second result = %+v applied %d, want accepted ci 2 applied 2",
127				second, *second.AppliedIndex)
128		}
129		if second.ApplyError != nil {
130			t.Fatalf("replacement incr must apply cleanly: %+v", second.ApplyError)
131		}
132		if kv := finalKVOf(t, out); !reflect.DeepEqual(kv, map[string]string{"count": "7"}) {
133			t.Fatalf("final kv = %v, want count=7", kv)
134		}
135		wantLog := []LogEntry{
136			entry(1, 1, "incr count=10"),
137			entry(2, 2, "incr count=-3"),
138		}
139		if !reflect.DeepEqual(out.FinalLog, wantLog) {
140			t.Fatalf("final log = %+v, want %+v", out.FinalLog, wantLog)
141		}
142	}
